SELECT 
FROM product


        AND INSTR(product.name, #{queryForm.name})


        AND INSTR(product.product_key, #{queryForm.productKey})


        AND product.category_id = #{queryForm.categoryId}


        AND product.device_type = #{queryForm.deviceType}


        AND product.status = #{queryForm.status}



    ORDER BY product.id DESC
